"""Spec 02.3 R8: generate docs/detection_baseline.md from benchmarks/detection/*.json. Do not edit the output by hand.

Inputs: eval_baseline.json (required); latency_cpu_torch*.json, eval_nms_ablation.json, class_confusion.json, and
tum_presence.json (each optional, so a missing section says so instead of failing).
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parents[1]
B = REPO / "benchmarks" / "detection"

CAVEATS = [
    "**Incomplete GT.** SUN 2D labels were not made for COCO. A correct detection of an unlabelled object (a book, "
    "a cup, a laptop) counts as a false positive, so precision and AP are **lower bounds**, especially for small "
    "desk objects.",
    "**Class mismatch.** The SUN-to-COCO mapping is not exact. SUN `table` includes coffee and side tables, and "
    "SUN `sofa_chair` (armchair) is mapped to COCO `couch`, although YOLO mostly calls armchairs `chair` (see "
    "Class confusion).",
    "**Domain shift.** The model is COCO-pretrained (mostly internet photos) and is **not fine-tuned**. SUN images "
    "are indoor shots from 4 depth sensors with different image quality.",
]

# Written after a visual review of benchmarks/detection/gallery/ (spec 02.2 AC5). Not automated.
GALLERY_OBSERVATIONS = [
    "Dense rows of chairs (lecture halls, e.g. `sun_kv2_001208`) are almost entirely missed. The many chairs in these "
    "scenes contribute to the 47% of chair GT with no matching detection, and kv2 (which has the most such scenes) has "
    "the lowest per-sensor mAP.",
    "Armchairs are detected as `chair` where SUN says `couch` (`sun_realsense_004894`, `sun_kv2_000326`, "
    "`sun_kv1_002649`). The class-confusion table quantifies this.",
    "Unlabelled-but-correct detections are common: books, papers, a laptop next to a GT `tv` (`sun_kv2_001208`). "
    "These are counted as FPs (caveat 1).",
    "Real errors: a waste bin called `cup` (`sun_realsense_004840`), a teddy bear called `person` (TUM fr3), and large "
    "objects cut by the image border missed (`sun_xtion_004165`, GT tv).",
    "The one2one head occasionally keeps two overlapping boxes of one class (e.g. two `book` boxes in TUM fr1), as "
    "noted in spec 02.1.",
    "On TUM, desk objects are detected consistently (keyboard, mouse, tv, laptop, book, bottle, chair), which is the "
    "input Phase 04 tracking needs.",
]


def f(x, nd=3):
    return "n/a" if x is None else f"{x:.{nd}f}"


def load(name):
    p = B / name
    return json.loads(p.read_text(encoding="utf-8")) if p.exists() else None


def main() -> int:
    e = load("eval_baseline.json")
    if e is None:
        raise SystemExit("missing benchmarks/detection/eval_baseline.json; run scripts/eval_detection.py first")
    h, v, t = e["run_header"], e["val"], e["test"]
    s, op = t["coco_summary"], t["at_operational"]
    n_cls = sum(1 for r in t["per_class"].values() if r["n_gt"] > 0)
    L = ["# Detection Baseline (spec 02.3)", "",
         "_Generated by `scripts/make_detection_report.py` from `benchmarks/detection/*.json`. Do not edit by hand; "
         "re-run the scripts instead._", "",
         f"**Model:** YOLO26-n, COCO-pretrained, no fine-tuning (`{h['weights']}`, sha256 `{h['weights_sha256'][:16]}…`), "
         f"head `{h['head']}`, input {h['imgsz']}×{h['imgsz']} letterbox, PyTorch {h['versions']['torch']} on CPU. "
         f"**Data:** SUN RGB-D test split, {t['n_images']:,} images, {t['n_gt']:,} GT boxes in the {n_cls} COCO classes "
         f"mapped by `configs/class_map.yaml` that have test GT. Git commit: `{h['git_commit'] or 'none (no commit yet)'}`.", "",
         "## Headline (test, measured)", "",
         "Read these numbers together with the three validity caveats:", ""]
    L += [f"{i}. {c}" for i, c in enumerate(CAVEATS, 1)] + [""]
    L += ["| Metric | Value |", "|---|---|",
          f"| mAP@50–95 | **{f(s['mAP'])}** |", f"| AP50 | **{f(s['AP50'])}** |", f"| AP75 | {f(s['AP75'])} |",
          f"| AR@100 | {f(s['AR100'])} |",
          f"| AP small / medium / large | {f(s['AP_small'])} / {f(s['AP_medium'])} / {f(s['AP_large'])} |",
          f"| Precision @ conf {v['conf_operational']}, IoU 0.5 | **{f(op['precision'])}** ({op['tp']:,} TP of {op['n_pred']:,} predictions) |",
          f"| Recall @ conf {v['conf_operational']}, IoU 0.5 | **{f(op['recall'])}** ({op['tp']:,} of {op['n_gt']:,} GT) |",
          f"| F1 @ conf {v['conf_operational']} | {f(op['f1'])} |", "",
          f"mAP averages the {n_cls} classes with test GT. COCOeval skips mapped classes with no test instances "
          f"({', '.join(k for k, r in t['per_class'].items() if r['n_gt'] == 0) or 'none'}). Settings: predictions kept down to "
          f"conf {e['eval_settings']['pred_conf_floor']}; COCO maxDets 100. "
          f"GT conversion (test): {e['gt_conversion']['test']['kept']:,} boxes kept, "
          f"{e['gt_conversion']['test']['unmapped']:,} in unmapped SUN classes dropped, "
          f"{e['gt_conversion']['test']['degenerate']} degenerate dropped.", ""]

    b = v["best_f1"]
    L += ["## Operating threshold (chosen on val only)", "",
          f"`conf_operational = {v['conf_operational']}` maximizes F1 at IoU 0.5 over the mapped classes on the **val** split "
          f"({v['n_images']} images, {v['n_gt']:,} GT): val P {f(b['precision'])}, R {f(b['recall'])}, F1 {f(b['f1'])} "
          f"(from {v['curve_points']:,} distinct score thresholds; `eval_baseline.json` → `val`). "
          "The test split was not used to choose it. Test F1 at this threshold is in the headline table.", "",
          "| conf (val) | Precision | Recall | F1 |", "|---|---|---|---|"]
    for row in v["pr_grid"][::2]:
        L.append(f"| {row['threshold']:.2f} | {f(row['precision'])} | {f(row['recall'])} | {f(row['f1'])} |")
    L += [""]

    L += ["## Per class (test)", "", f"Low-n = fewer than {e['eval_settings']['low_n_below']} test GT instances; "
          "treat those APs as anecdotal.", "", "| Class | GT | AP50 | AP50–95 | Note |", "|---|---|---|---|---|"]
    for name, r in sorted(t["per_class"].items(), key=lambda kv: -kv[1]["n_gt"]):
        if r["n_gt"] == 0:
            continue
        L.append(f"| {name} | {r['n_gt']:,} | {f(r['AP50'])} | {f(r['AP'])} | {'low-n' if r['low_n'] else ''} |")
    L += [""]

    L += ["## Per sensor (test)", "", "| Sensor | Images | GT | mAP | AP50 | P @ op | R @ op |", "|---|---|---|---|---|---|---|"]
    for sn, r in t["per_sensor"].items():
        a = r["at_operational"]
        L.append(f"| {sn} | {r['n_images']:,} | {r['n_gt']:,} | {f(r['mAP'])} | {f(r['AP50'])} | {f(a['precision'])} | {f(a['recall'])} |")
    L += ["", "The sensors also differ in scene mix (kv2 has many dense classrooms), so this table cannot separate image "
          "quality from content.", ""]

    sv = t["sensitivity_desk_ignore"]
    L += ["## Sensitivity: SUN `desk` as an ignore region (R5)", "",
          f"{sv['n_desk_ignore_regions']:,} desk boxes become ignore regions for `dining table`, so a prediction on a desk is "
          "neither TP nor FP. **The strict number stays the headline.**", "",
          "| | dining table AP50 | dining table AP50–95 | all-class mAP |", "|---|---|---|---|",
          f"| strict | {f(sv['strict']['AP50'])} | {f(sv['strict']['AP'])} | {f(sv['all_classes_mAP_strict'])} |",
          f"| desk as ignore | {f(sv['desk_as_ignore']['AP50'])} | {f(sv['desk_as_ignore']['AP'])} | {f(sv['all_classes_mAP_desk_ignore'])} |", ""]

    cc = load("class_confusion.json")
    L += ["## Class confusion (test, at the operating threshold)", ""]
    if cc:
        L += ["For each SUN GT box, the class of the highest-IoU prediction, if that IoU is ≥ 0.5 (`class_confusion.json`). "
              "This is diagnostic only: it was measured on test, so **the class map was not changed because of it**. "
              "Any change would have to be justified on val.", "",
              "| SUN class | GT | Best-matching prediction class (count) |", "|---|---|---|"]
        for k, r in cc["test"].items():
            L.append(f"| {k} | {r['n_gt']:,} | " + ", ".join(f"{c} {n:,}" for c, n in r["best_iou>=0.5_pred_class"].items()) + " |")
    else:
        L.append("Not computed.")
    L += [""]

    ab = load("eval_nms_ablation.json")
    L += ["## Head ablation: one2one (NMS-free) vs one2many + NMS", ""]
    if ab:
        a_s, a_op = ab["test"]["coco_summary"], ab["test"]["at_operational"]
        L += ["The same weights and test images. Each head's operating threshold was chosen on its own val run.", "",
              "| Head | mAP | AP50 | AR@100 | conf_op (val) | P @ op | R @ op | F1 @ op |", "|---|---|---|---|---|---|---|---|",
              f"| one2one (default) | {f(s['mAP'])} | {f(s['AP50'])} | {f(s['AR100'])} | {v['conf_operational']} | {f(op['precision'])} | {f(op['recall'])} | {f(op['f1'])} |",
              f"| one2many + NMS (IoU {ab['run_header']['iou_nms']}) | {f(a_s['mAP'])} | {f(a_s['AP50'])} | {f(a_s['AR100'])} | {ab['val']['conf_operational']} | {f(a_op['precision'])} | {f(a_op['recall'])} | {f(a_op['f1'])} |", "",
              f"mAP differs by {abs(s['mAP'] - a_s['mAP']):.3f} and F1 at the operating point by {abs(op['f1'] - a_op['f1']):.3f}, "
              "which is within what one would expect from noise on this data. The NMS head trades precision for recall "
              "at its own threshold. **one2one stays the default:** equal accuracy, higher AR@100, and no NMS step to "
              "port to ONNX in Phase 06.", ""]
    else:
        L += ["Not run yet.", ""]

    L += ["## Latency (CPU, measured)", ""]
    lat = [(p.stem, json.loads(p.read_text(encoding="utf-8"))) for p in sorted(B.glob("latency_cpu_torch*.json"))]
    if lat:
        m = lat[0][1]
        L += [f"PyTorch CPU, {m['machine']['cpu']}, {m['provenance']['threads']} threads, input {m['provenance']['imgsz']}, "
              f"head `{m['provenance']['head']}`, 10 warm-up frames excluded, peak RSS ≈ {m['peak_rss_mb']:.0f} MB. "
              f"Power: plugged in = {m['power_before']['plugged_in']}, Windows **Balanced** plan; the machine was also under "
              "memory pressure (~0.8 GB free RAM). **Decode** (JPEG read) is reported separately and is not part of "
              "detector latency. This is the Phase 06 baseline to compare against, not a tuned number.", "",
              "| Run | Frames | Detector median (ms) | Detector p95 (ms) | Infer median | Decode median | FPS (from median) |",
              "|---|---|---|---|---|---|---|"]
        for stem, r in lat:
            for name, x in r["lists"].items():
                st = x["stages_ms"]
                L.append(f"| {stem.replace('latency_cpu_torch', 'run1') if stem == 'latency_cpu_torch' else stem.replace('latency_cpu_torch_', '')} · {name} | "
                         f"{x['n_frames']} | {st['detector']['median']:.0f} | {st['detector']['p95']:.0f} | "
                         f"{st['infer']['median']:.0f} | {st['decode']['median']:.1f} | {x['detector_fps_from_median']:.1f} |")
        L += ["", "Run-to-run spread is large at p95 (background load and memory pressure), and SUN decode times differ "
              "because run 1 read cold from disk. Every list feeds the same 640×640 tensor to the network, so differences "
              "in infer time between lists reflect machine state, not image content.", ""]
    else:
        L += ["Not measured yet.", ""]

    L += ["## Gallery review (spec 02.2 AC5)", "", "Overlays: `benchmarks/detection/gallery/` (green = prediction at "
          "conf_operational, orange = SUN GT of mapped classes). Patterns seen:", ""]
    L += [f"- {o}" for o in GALLERY_OBSERVATIONS] + [""]

    tp = load("tum_presence.json")
    if tp:
        L += ["## TUM object presence", "", "| Sequence | Frames | With ≥ 1 detection |", "|---|---|---|"]
        for seq, x in tp["sequences"].items():
            L.append(f"| {seq} | {x['n_frames']:,} | {x['frames_with_detection']:,} ({100 * x['share_with_detection']:.1f}%) |")
        L += ["", "Per-class counts are in `docs/data_quality_report.md`.", ""]

    chair = t["per_class"].get("chair", {})
    L += ["## Phase 02 exit check (AC5)", "",
          "- No target mAP was set. This baseline is a measurement.",
          f"- Sanity: chair AP50 = {f(chair.get('AP50'))} (expected clearly > 0): {'✅' if (chair.get('AP50') or 0) > 0.1 else '❌'}",
          "- Evaluator validation tests: `tests/test_eval_detection.py` (perfect → 1, empty → 0, hand-computed toy AP, "
          "mapping, ignore regions, F1 picker).", ""]
    (REPO / "docs" / "detection_baseline.md").write_text("\n".join(L), encoding="utf-8")
    print("wrote docs/detection_baseline.md")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
